package com.biscord.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;
import java.net.URI;import java.util.ArrayList;
public class MainActivity extends Activity {
 private WebView web;private String origin="";private ValueCallback<Uri[]> files;private PermissionRequest media;private boolean showingError=false;
 private String validate(String value)throws Exception{URI u=new URI(value.trim());if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getPort()!=-1&&u.getPort()!=443)throw new Exception();return "https://"+u.getHost().toLowerCase();}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(32,32,36));getWindow().setNavigationBarColor(Color.rgb(32,32,36));origin=getPreferences(0).getString("server","https://biscord-ashy.vercel.app");if(origin.isEmpty())configure();else load();}
 private void configure(){if(web!=null){web.destroy();web=null;}LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,40,28,24);root.setBackgroundColor(Color.rgb(32,32,36));TextView title=new TextView(this);title.setText("vulcord");title.setTextSize(30);title.setTextColor(Color.WHITE);root.addView(title);TextView description=new TextView(this);description.setText("Conecte-se ao seu servidor vulcord. Use o endereço HTTPS público informado pelo administrador.");description.setTextColor(Color.LTGRAY);description.setPadding(0,20,0,24);root.addView(description);EditText input=new EditText(this);input.setSingleLine(true);input.setHint("https://seu-biscord.com");input.setInputType(17);input.setText(origin);input.setTextColor(Color.WHITE);input.setHintTextColor(Color.GRAY);root.addView(input);Button button=new Button(this);button.setText("Conectar");root.addView(button);TextView error=new TextView(this);error.setTextColor(0xffffa0a0);root.addView(error);button.setOnClickListener(v->{try{origin=validate(input.getText().toString());getPreferences(0).edit().putString("server",origin).apply();load();}catch(Exception e){error.setText("Informe um endereço HTTPS válido, sem usuário ou senha.");}});setContentView(root);}
 private boolean trusted(Uri uri){return origin.equals(uri.getScheme()+"://"+uri.getHost())&&(uri.getPort()==-1||uri.getPort()==443)&&uri.getUserInfo()==null;}
 private boolean appRoute(Uri uri){String p=uri.getPath();return p!=null&&(p.startsWith("/channels/")||p.equals("/login")||p.equals("/register")||p.equals("/forgot-password")||p.equals("/reset-password")||p.startsWith("/invite/"));}
 private void load(){showingError=false;web=new WebView(this);web.setBackgroundColor(Color.rgb(32,32,36));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(false);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri uri=request.getUrl();if(trusted(uri)&&appRoute(uri))return false;if("https".equals(uri.getScheme())||"http".equals(uri.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){}return true;}
 @Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())connectionError();}
 @Override public void onReceivedHttpError(WebView view,WebResourceRequest request,WebResourceResponse response){if(request.isForMainFrame()&&response.getStatusCode()>=400)connectionError();}
 @Override public void onPageFinished(WebView view,String url){CookieManager.getInstance().flush();}
 });web.setWebChromeClient(new WebChromeClient(){
 @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(files!=null)files.onReceiveValue(null);files=callback;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("image/*");try{startActivityForResult(intent,42);return true;}catch(Exception e){files=null;callback.onReceiveValue(null);return false;}}
 @Override public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!trusted(request.getOrigin())){request.deny();return;}if(media!=null){request.deny();return;}media=request;ArrayList<String> permissions=new ArrayList<>();for(String resource:request.getResources()){if(PermissionRequest.RESOURCE_AUDIO_CAPTURE.equals(resource)&&checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED)permissions.add("android.permission.RECORD_AUDIO");if(PermissionRequest.RESOURCE_VIDEO_CAPTURE.equals(resource)&&checkSelfPermission("android.permission.CAMERA")!=PackageManager.PERMISSION_GRANTED)permissions.add("android.permission.CAMERA");}if(permissions.isEmpty())grantMedia();else requestPermissions(permissions.toArray(new String[0]),43);});}
 @Override public void onPermissionRequestCanceled(PermissionRequest request){if(media==request)media=null;}
 });setContentView(web);web.loadUrl(origin+"/channels/@me");}
 private void grantMedia(){if(media==null)return;ArrayList<String> allowed=new ArrayList<>();for(String r:media.getResources())if(PermissionRequest.RESOURCE_AUDIO_CAPTURE.equals(r)&&checkSelfPermission("android.permission.RECORD_AUDIO")==0||PermissionRequest.RESOURCE_VIDEO_CAPTURE.equals(r)&&checkSelfPermission("android.permission.CAMERA")==0)allowed.add(r);if(allowed.isEmpty())media.deny();else media.grant(allowed.toArray(new String[0]));media=null;}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==43)grantMedia();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42&&files!=null){files.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null?new Uri[]{data.getData()}:null);files=null;}}
 private void connectionError(){if(showingError||isFinishing())return;showingError=true;new AlertDialog.Builder(this).setTitle("Servidor indisponível").setMessage("Confira a conexão e se o servidor está ligado.").setPositiveButton("Tentar novamente",(d,w)->{showingError=false;web.loadUrl(origin+"/channels/@me");}).setNeutralButton("Alterar servidor",(d,w)->{showingError=false;configure();}).setNegativeButton("Fechar",(d,w)->finish()).setCancelable(false).show();}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setTitle("vulcord").setItems(new String[]{"Continuar","Alterar servidor","Fechar"},(d,w)->{if(w==1)configure();if(w==2)finish();}).show();}
 @Override protected void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}
